window.PORTFOLIO={identity:{firstName:"Mehdi",lastName:"LAFAY",formation:"BUT Informatique \u2014 2\u1D49 ann\xE9e",email:"mehdi.lafay@edu.univ-fcomte.fr",site:"uspv-judo.fr",siteUrl:"https://uspv-judo.fr"},nav:[{id:"accueil",label:"Accueil",num:"1"},{id:"technique",label:"Technique",num:"2"},{id:"suivi",label:"Suivi de projet",num:"3"},{id:"integration",label:"Int\xE9gration",num:"4"}],accueil:{kicker:"Portfolio de stage \xB7 BUT 2",title:"Bienvenue sur mon portfolio",intro:`<div style="float: right; margin: 0 0 15px 20px; width: 200px; text-align: center;">
         <picture>
           <source srcset="assets/img/photo-enfant-200.webp 1x, assets/img/photo-enfant.webp 2x" type="image/webp">
           <img src="assets/img/photo-enfant.jpg" alt="Moi en judoka, il y a tr\xE8s longtemps" width="200" height="319" loading="lazy" decoding="async" style="width: 100%; height: auto; border-radius: 6px; border: 1px solid var(--line);" />
         </picture>
         <p style="font-size: 11px; color: var(--faint); font-style: italic; margin-top: 6px; line-height: 1.3;">Une photo venant d'une \xE9poque lointaine, tr\xE8s lointaine...</p>
       </div>
       <p>Ce site pr\xE9sente les <strong>savoir-faire</strong> que j'ai mobilis\xE9s et d\xE9velopp\xE9s
       pendant mon <strong>stage de 2\u1D49 ann\xE9e de BUT Informatique</strong>, r\xE9alis\xE9 du
       <strong>7 avril au 5 juin 2026</strong> pour le club <strong>USPV Judo</strong>
       (Pont-de-Roide-Vermondans) \u2014 projet r\xE9compens\xE9 par la <strong>meilleure note de la promotion avec 17,80 / 20</strong> (sur 46 \xE9tudiants). Il s'organise en trois volets \u2014
       <em>technique</em>, <em>suivi de projet</em> et <em>int\xE9gration en entreprise</em> \u2014
       chacun illustr\xE9 par des <strong>traces concr\xE8tes</strong> issues du projet et
       compl\xE9t\xE9 par un <strong>bilan</strong> qui analyse mon niveau d'expertise.</p>
       <div class="distinction-card">
         <div class="distinction-text">
           <strong>Distinction :</strong> Pour ce projet de stage de deuxi\xE8me ann\xE9e, j'ai obtenu la <strong>meilleure note sur une promotion de 46 \xE9tudiants avec 17,80 / 20</strong>.
         </div>
       </div>`,archTitle:"L'architecture de la plateforme r\xE9alis\xE9e",entreprise:{title:"Le club & les personnes",html:`<p><strong>USPV Judo</strong> est le <strong>club historique de judo</strong> de
         Pont-de-Roide-Vermondans (Doubs), une <strong>association loi 1901</strong> anim\xE9e par des
         b\xE9n\xE9voles et affili\xE9e \xE0 la <strong>F\xE9d\xE9ration Fran\xE7aise de Judo (FFJDA)</strong>. Les cours
         ont lieu au dojo Georges Mairot.</p>
         <p class="muted" style="margin-bottom:4px"><strong>Personnes impliqu\xE9es :</strong></p>
         <ul class="clean">
           <li><strong>Mon tuteur</strong> (membre du bureau) : il exprimait les besoins, fixait les
               priorit\xE9s et validait chaque avanc\xE9e lors des r\xE9unions de suivi.</li>
           <li>Le <strong>bureau du club</strong> (b\xE9n\xE9voles non informaticiens) \u2014 les
               <em>utilisateurs finaux</em> de l'espace de gestion.</li>
           <li>Les <strong>familles adh\xE9rentes</strong> \u2014 le public du site et de la pr\xE9-inscription.</li>
           <li><strong>Moi</strong> \u2014 stagiaire d\xE9veloppeur, en charge de la conception et de la
               r\xE9alisation compl\xE8te de la plateforme.</li>
         </ul>
         <p style="margin-top:8px"><strong>Moyens de travail :</strong> poste de d\xE9veloppement,
         d\xE9p\xF4t <strong>Git/GitHub</strong> avec <strong>int\xE9gration continue</strong>, base
         <strong>PostgreSQL</strong>, serveur <strong>VPS</strong> (Nginx + PM2), et un
         <strong>cahier des charges</strong> + <strong>dossier d'architecture technique</strong>
         r\xE9dig\xE9s en amont.</p>`},sujet:{title:"Le contexte & le sujet",html:`<p><strong>Le point de d\xE9part :</strong> le club disposait d'un
         <strong>ancien site statique obsol\xE8te</strong>, impossible \xE0 mettre \xE0 jour par les b\xE9n\xE9voles.
         Les <strong>inscriptions se faisaient sur papier</strong>, il n'existait ni espace adh\xE9rent,
         ni outil pour communiquer horaires, \xE9v\xE9nements et tarifs.</p>
         <p><strong>Le sujet :</strong> concevoir et d\xE9velopper enti\xE8rement une nouvelle plateforme web
         pour le club \u2014 un <em>site public</em>, un <em>espace famille</em> et un
         <em>back-office d'administration</em> \u2014 avec la <strong>pr\xE9-inscription en ligne</strong>
         comme fonctionnalit\xE9 centrale.</p>
         <p><strong>Enjeux & objectifs :</strong> <strong>d\xE9mat\xE9rialiser les inscriptions</strong> dans
         le respect du <strong>RGPD</strong> (mineurs, droit \xE0 l'image) ; <strong>autonomiser le bureau</strong>
         b\xE9n\xE9vole pour qu'il g\xE8re le contenu sans technicien ; <strong>suivre les adh\xE9rents</strong>
         (dossiers, ceintures) ; le tout <strong>s\xE9curis\xE9</strong>, maintenable et d\xE9ploy\xE9 en production.</p>`},savoirFaire:{title:"Les savoir-faire g\xE9n\xE9raux mis en jeu",intro:`Le sujet a mobilis\xE9 des savoir-faire dans plusieurs domaines. Ceux ci-dessous sont
         <strong>d\xE9taill\xE9s et analys\xE9s</strong> dans les trois pages suivantes (cliquez pour y acc\xE9der) :`,groups:[{page:"technique",pageLabel:"Technique",items:[{label:"Concevoir et exploiter une base de donn\xE9es relationnelle",color:"#2196c9",target:"technique/bilan"},{label:"D\xE9velopper un back-end web s\xE9curis\xE9",color:"#1ea672",target:"technique/bilan"},{label:"D\xE9velopper une interface web dynamique",color:"#8a63e8",target:"technique/bilan"}]},{page:"suivi",pageLabel:"Suivi de projet",items:[{label:"Piloter un projet de d\xE9veloppement, du besoin \xE0 la livraison",color:"#e0871a",target:"suivi/bilan"}]},{page:"integration",pageLabel:"Int\xE9gration",items:[{label:"S'int\xE9grer et accompagner les utilisateurs en entreprise",color:"#d9576f",target:"integration/bilan"}]}]}},technique:{kicker:"Volet 1 \xB7 C\xF4t\xE9 technique informatique",title:"Technique",summary:`Le c\u0153ur du stage : la conception et le d\xE9veloppement de la plateforme. Six traces couvrent
       les trois grands domaines techniques \u2014 <strong>base de donn\xE9es</strong>, <strong>back-end s\xE9curis\xE9</strong>
       et <strong>front-end</strong> (deux traces chacun) \u2014 suivies d'un bilan de mes savoir-faire
       techniques g\xE9n\xE9raux.`,subpages:[{id:"trace-1",kind:"trace",number:1,tab:"BdD \xB7 Sch\xE9ma",title:"Mod\xE9liser la base de donn\xE9es relationnelle",domain:{label:"Base de donn\xE9es",color:"#2196c9"},skills:[{id:"se1.1",label:"Mod\xE9liser des entit\xE9s et leurs relations",color:"#2196c9"},{id:"se1.2",label:"Garantir l'int\xE9grit\xE9 r\xE9f\xE9rentielle",color:"#1ea672"},{id:"se1.3",label:"Choisir les types, contraintes et index",color:"#e0871a"}],figure:{type:"svg",file:"database/schema.sql",caption:"Sch\xE9ma relationnel (extrait) de la base PostgreSQL con\xE7ue pour la plateforme \u2014 24 tables au total.",legend:[{n:1,cls:"",text:"Table grade : progression des ceintures (1 judoka \u2192 N grades)"},{n:2,cls:"h2",text:"ON DELETE CASCADE : supprimer un dossier efface ses d\xE9pendances"},{n:3,cls:"h3",text:"R\xE9f\xE9rence polymorphique (jeton de session) sans cl\xE9 \xE9trang\xE8re"}]},general:`<p>Cette trace est le <strong>sch\xE9ma relationnel</strong> de la base que j'ai mod\xE9lis\xE9e
           (<code>schema.sql</code>). Elle structure toutes les donn\xE9es du club : familles, dossiers
           d'inscription, pratiquants, ceintures, paiements, contenus du site et tournois.</p>
           <p>C'est la <strong>fondation du projet</strong> : avant tout d\xE9veloppement, j'ai d\xFB traduire
           le fonctionnement du club en entit\xE9s. Le point ((1)), la table <code>grade</code>, est propre
           au judo (suivi des ceintures) ; la m\xE9canique du point ((2)) est exploit\xE9e par la
           <strong>transaction de la trace n\xB02</strong>.</p>`,details:[{skillId:"se1.1",html:`J'ai traduit le m\xE9tier du club en [[se1.1|entit\xE9s et relations]] : une
                   <code>famille</code> d\xE9pose un ou plusieurs <code>dossier</code>s, chacun regroupant
                   des <code>enfant</code>s (pratiquants), un <code>representant</code> l\xE9gal et une
                   <code>trace_legale</code> (consentements RGPD). Au point ((1)), chaque pratiquant
                   poss\xE8de un historique de <strong>grades</strong>.`},{skillId:"se1.2",html:`Chaque relation est prot\xE9g\xE9e par une cl\xE9 \xE9trang\xE8re : au point ((2)),
                   [[se1.2|<code>ON DELETE CASCADE</code>]] supprime automatiquement enfants, paiements et
                   documents d'un dossier effac\xE9, tandis que <code>ON DELETE SET NULL</code> <em>conserve</em>
                   un dossier m\xEAme si le compte famille dispara\xEEt.`},{skillId:"se1.3",html:`J'ai [[se1.3|choisi des types et des contraintes adapt\xE9s]] (<code>NUMERIC(10,2)</code>
                   pour les montants, <code>UNIQUE</code> sur les e-mails, <code>JSONB</code> pour le d\xE9tail
                   du droit \xE0 l'image) et ajout\xE9 <strong>plus de 30 index</strong>, dont des index composites
                   <code>(user_id, role)</code>. Le point ((3)) montre un choix assum\xE9 : <code>refresh_token</code>
                   pointe vers <em>deux</em> tables possibles, donc <strong>sans</strong> cl\xE9 \xE9trang\xE8re, ce que
                   j'ai document\xE9 en commentaire.`}]},{id:"trace-2",kind:"trace",number:2,tab:"BdD \xB7 Transaction",title:"Garantir l'int\xE9grit\xE9 des donn\xE9es via une transaction SQL",domain:{label:"Base de donn\xE9es \xB7 Transactions",color:"#2196c9"},skills:[{id:"se2.1",label:"Garantir l'atomicit\xE9 par une transaction",color:"#2196c9"},{id:"se2.2",label:"G\xE9rer les acc\xE8s concurrents",color:"#e0533f"},{id:"se2.3",label:"Ins\xE9rer des donn\xE9es li\xE9es et trac\xE9es",color:"#1ea672"}],figure:{type:"code",lang:"js",file:"server/api/inscription.post.ts",caption:"Pr\xE9-inscription d'une famille : une transaction \xE9crit atomiquement dans 5 tables li\xE9es.",legend:[{n:1,cls:"",text:"Transaction atomique : tout r\xE9ussit, ou tout est annul\xE9"},{n:2,cls:"h2",text:"Anti-concurrence : ON CONFLICT DO NOTHING"},{n:3,cls:"h3",text:"Donn\xE9es li\xE9es : un dossier \u2192 N pratiquants (boucle)"},{n:4,cls:"h4",text:"Consentements RGPD horodat\xE9s et versionn\xE9s"}],lines:[["// inscription.post.ts \u2014 pr\xE9-inscription d'une famille (extrait)",0],["const { praticants, representant, consentements } = validateInscriptionPayload(body)",0],["await verifyTurnstile(body?.captchaToken)        // anti-bot (captcha)",0],["",0],["await withTransaction(async (client) => {        // tout ou rien",1],["  // ON CONFLICT \xE9vite la collision si deux envois arrivent en m\xEAme temps",0],["  const ins = await client.query(",2],["    `INSERT INTO famille (email, nom, prenom, telephone, adresse, actif)",2],["     VALUES ($1, $2, $3, $4, $5, false)",2],["     ON CONFLICT (email) DO NOTHING RETURNING id`,",2],["    [email, representant.nom, representant.prenom, tel, adresse])",2],["  const familleId = ins.rows[0]?.id ?? (await refetchId(client, email))",0],["",0],["  const d = await client.query(`INSERT INTO dossier (famille_id, statut)",0],["    VALUES ($1, 'en_attente') RETURNING id`, [familleId])",0],["  const dossierId = d.rows[0].id",0],["",0],["  for (const p of praticants) {                  // un dossier \u2192 plusieurs judokas",3],["    await client.query(`INSERT INTO enfant",3],["      (dossier_id, nom, prenom, date_naissance, categorie, discipline)",3],["      VALUES ($1, $2, $3, $4, $5, $6)`, [dossierId, p.nom, p.prenom,",3],["      p.date_naissance, p.categorie, p.discipline])",3],["  }",3],["",0],["  await client.query(`INSERT INTO trace_legale (dossier_id,",4],["    consentement_donnees, droit_image, droit_image_details,",4],["    acceptation_reglement, version_reglement) VALUES ($1,$2,$3,$4,$5,$6)`,",4],["    [dossierId, c.donnees, c.image, JSON.stringify(details), c.reglement, version])",4],["})                                                // COMMIT implicite",1]]},general:`<p>La <strong>trace n\xB02</strong> est l'endpoint qui enregistre une pr\xE9-inscription
           (<code>inscription.post.ts</code>). Une seule soumission doit \xE9crire dans <strong>cinq tables
           li\xE9es</strong> (<code>famille</code>, <code>dossier</code>, <code>enfant</code>,
           <code>representant</code>, <code>trace_legale</code>) \u2014 sans jamais laisser un dossier \xE0 moiti\xE9 cr\xE9\xE9.</p>
           <p>Elle met \xAB en vie \xBB le mod\xE8le de la <strong>trace n\xB01</strong> : c'est ici que les relations et
           les cl\xE9s \xE9trang\xE8res prennent tout leur sens, sur la fonctionnalit\xE9 la plus sensible du projet.</p>`,details:[{skillId:"se2.1",html:`Au point ((1)), tout passe par une [[se2.1|transaction]] (<code>withTransaction</code>) :
                   si une seule insertion \xE9choue, <strong>toutes</strong> sont annul\xE9es (rollback). Impossible
                   d'obtenir une famille sans dossier ou un dossier sans repr\xE9sentant.`},{skillId:"se2.2",html:`Au point ((2)), je [[se2.2|g\xE8re les acc\xE8s concurrents]] : si deux parents valident le
                   formulaire au m\xEAme instant, <code>ON CONFLICT (email) DO NOTHING</code> emp\xEAche la
                   violation de contrainte <code>UNIQUE</code> ; je relis alors la ligne existante.`},{skillId:"se2.3",html:`Aux points ((3)) et ((4)), j'[[se2.3|ins\xE8re les donn\xE9es li\xE9es]] : une boucle cr\xE9e un
                   <code>enfant</code> par judoka, puis j'enregistre la <strong>trace l\xE9gale</strong> (RGPD)
                   horodat\xE9e et versionn\xE9e. Toutes les valeurs passent par des
                   <strong>requ\xEAtes param\xE9tr\xE9es</strong> (<code>$1, $2\u2026</code>), donc aucune injection SQL.`}]},{id:"trace-3",kind:"trace",number:3,tab:"Back-end \xB7 Auth",title:"S\xE9curiser la connexion \xE0 l'espace de gestion (bcrypt, JWT)",domain:{label:"Back-end \xB7 S\xE9curit\xE9",color:"#1ea672"},skills:[{id:"se3.1",label:"Hacher les mots de passe (bcrypt)",color:"#1ea672"},{id:"se3.2",label:"G\xE9rer des sessions par jetons (JWT + refresh)",color:"#2196c9"},{id:"se3.3",label:"Prot\xE9ger le cookie (HttpOnly)",color:"#8a63e8"},{id:"se3.4",label:"S\xE9curiser la configuration (fail-fast)",color:"#e0533f"}],figure:{type:"code",lang:"js",file:"server/utils/auth.ts + api/auth/login.post.ts",caption:"Connexion d'un membre du bureau : v\xE9rification bcrypt, JWT court et cookie HttpOnly.",legend:[{n:1,cls:"",text:"Hachage bcrypt (co\xFBt 12) + v\xE9rification"},{n:2,cls:"h2",text:"JWT court (15 min) + refresh token hach\xE9 en base"},{n:3,cls:"h3",text:"Cookie HttpOnly / Secure / SameSite"},{n:4,cls:"h4",text:"Fail-fast : refus de d\xE9marrer sans vrai secret"}],lines:[["// auth.ts \u2014 le mot de passe n'est jamais stock\xE9 en clair",0],["export const hashPassword = (p) => bcrypt.hash(p, 12)   // co\xFBt 12 (pr\xE9co. DAT)",1],["",0],["// En production, on refuse de d\xE9marrer avec un secret par d\xE9faut",0],["if (NODE_ENV === 'production' && JWT_SECRET.includes('fallback'))",4],["  throw new Error('JWT_SECRET manquant en production')",4],["",0],["// login.post.ts \u2014 v\xE9rification de l'identit\xE9",0],["const u = (await query('SELECT id, role, mot_de_passe, actif",0],["           FROM utilisateur WHERE email = $1', [email])).rows[0]",0],["if (!u || !u.actif) throw createError({ statusCode: 401 })",0],["if (!(await bcrypt.compare(motDePasse, u.mot_de_passe)))   // comparaison bcrypt",1],["  throw createError({ statusCode: 401, statusMessage: 'Identifiants incorrects.' })",1],["",0],["const token   = jwt.sign({ id: u.id, role: u.role }, JWT_SECRET, { expiresIn: '15m' })",2],["const refresh = crypto.randomBytes(40).toString('hex')     // session longue",2],["await query('DELETE FROM refresh_token WHERE user_id=$1 AND role=$2', [u.id, u.role])",2],["await query(`INSERT INTO refresh_token (user_id, role, token_hash, expires_at)",2],["  VALUES ($1,$2,$3, NOW() + INTERVAL '7 days')`, [u.id, u.role, sha256(refresh)])",2],["",0],["setCookie(event, 'uspv_admin_token', token,",3],["  { httpOnly: true, secure: true, sameSite: 'strict' })   // inaccessible au JS",3]]},general:`<p>La <strong>trace n\xB03</strong> est la <strong>connexion</strong> \xE0 l'espace de gestion
           (<code>auth.ts</code> + <code>login.post.ts</code>). Tout le back-office du bureau repose sur elle :
           c'est l'authentification qui conditionne le syst\xE8me de <strong>r\xF4les</strong> et l'acc\xE8s aux donn\xE9es
           des adh\xE9rents.</p>
           <p>La s\xE9curit\xE9 des <strong>donn\xE9es personnelles de mineurs</strong> \xE9tait un enjeu fort : une fuite
           serait inacceptable pour le club.</p>`,details:[{skillId:"se3.1",html:`Au point ((1)), je [[se3.1|hache le mot de passe avec bcrypt]] (un algorithme de brouillage) (co\xFBt 12) : il n'est
                   <strong>jamais stock\xE9 en clair</strong>, et la comparaison se fait par
                   <code>bcrypt.compare</code> \u2014 r\xE9sistant aux attaques par dictionnaire.`},{skillId:"se3.2",html:`Au point ((2)), je [[se3.2|g\xE8re la session par jetons]] : un <strong>JWT (jeton de s\xE9curit\xE9) de 15 min</strong>
                   pour les requ\xEAtes, et un <strong>refresh token</strong> de 7 jours <em>hach\xE9 en base</em>
                   (jamais en clair). Je r\xE9voque l'ancienne session avant d'en cr\xE9er une nouvelle.`},{skillId:"se3.3",html:`Au point ((3)), le jeton part dans un [[se3.3|cookie <code>HttpOnly</code>]] (+ <code>Secure</code>,
                   <code>SameSite=strict</code>) : inaccessible au JavaScript, il r\xE9siste au vol par XSS.`},{skillId:"se3.4",html:`Au point ((4)), j'applique le principe [[se3.4|<em>fail-fast</em>]] : en production, le serveur
                   <strong>refuse de d\xE9marrer</strong> si le secret JWT est rest\xE9 la valeur par d\xE9faut \u2014 une
                   erreur de d\xE9ploiement impossible \xE0 ignorer.`}]},{id:"trace-4",kind:"trace",number:4,tab:"Back-end \xB7 D\xE9fense",title:"Filtrer les requ\xEAtes API via une cha\xEEne de middlewares",domain:{label:"S\xE9curit\xE9 \xB7 Syst\xE8me",color:"#e0533f"},skills:[{id:"se4.1",label:"Limiter le d\xE9bit des requ\xEAtes (rate-limit)",color:"#e0533f"},{id:"se4.2",label:"Pr\xE9venir les attaques CSRF",color:"#e0871a"},{id:"se4.3",label:"Durcir les en-t\xEAtes HTTP",color:"#8a63e8"},{id:"se4.4",label:"Empiler les middlewares (cha\xEEne)",color:"#1ea672"}],figure:{type:"code",lang:"js",file:"server/middleware/ (01-rate-limit, 02-csrf, 00-headers)",caption:"Cha\xEEne de middlewares : chaque requ\xEAte API traverse plusieurs contr\xF4les avant le code m\xE9tier.",legend:[{n:1,cls:"",text:"Quotas par type de route \u2192 429 si d\xE9passement"},{n:2,cls:"h2",text:"Compteur par adresse IP (fen\xEAtre glissante)"},{n:3,cls:"h3",text:"Jeton anti-CSRF sur les \xE9critures authentifi\xE9es \u2192 403"},{n:4,cls:"h4",text:"En-t\xEAtes de s\xE9curit\xE9 (HSTS, nosniff, CSP)"}],lines:[["// 01-rate-limit.ts \u2014 un quota diff\xE9rent selon la sensibilit\xE9 de la route",0],["const rules = [",0],["  { name:'login',  match:p=>p==='/api/auth/login',       windowMs:600000, max:10  },",1],["  { name:'admin',  match:p=>p.startsWith('/api/admin'),  windowMs:60000,  max:120 },",1],["  { name:'public', match:p=>p.startsWith('/api/public'), windowMs:60000,  max:240 },",1],["]",0],["const rule = rules.find(r => r.match(path)); if (!rule) return",0],["const key   = `${rule.name}:${getClientIp(event, trustProxy)}`  // par IP",2],["const entry = bump(buckets, key, rule.windowMs)",2],["if (entry.count > rule.max)",1],["  throw createError({ statusCode: 429, statusMessage: 'Trop de requ\xEAtes.' })",1],["",0],["// 02-csrf.ts \u2014 sur les \xE9critures d'un utilisateur connect\xE9",0],["if (!SAFE_METHODS.has(method) && getAuthUser(event)) {",3],["  const token = getHeader(event, 'x-csrf-token') || ''",3],["  if (!await validateCsrfToken(user, token))",3],["    throw createError({ statusCode: 403, statusMessage: 'CSRF invalide.' })",3],["}",3],["",0],["// 00-security-headers.ts \u2014 pos\xE9s sur toutes les r\xE9ponses",0],["setHeader(event, 'Strict-Transport-Security', 'max-age=31536000; includeSubDomains')",4],["setHeader(event, 'X-Content-Type-Options', 'nosniff')",4]]},general:`<p>La <strong>trace n\xB04</strong> est la <strong>cha\xEEne de middlewares</strong> (des filtres interm\xE9diaires) du serveur. Avant
           d'atteindre le code m\xE9tier, chaque requ\xEAte API traverse plusieurs <strong>barri\xE8res</strong>
           num\xE9rot\xE9es (<code>00-</code> \xE0 <code>05-</code>) : en-t\xEAtes de s\xE9curit\xE9, limite de d\xE9bit, v\xE9rification
           CSRF\u2026</p>
           <p>C'est l'application du principe de <strong>d\xE9fense en profondeur</strong> : si une protection est
           contourn\xE9e, les autres tiennent encore. Indispensable pour un site expos\xE9 sur Internet.</p>`,details:[{skillId:"se4.1",html:`Aux points ((1)) et ((2)), je [[se4.1|limite le d\xE9bit]] : la connexion est plafonn\xE9e \xE0
                   <strong>10 tentatives / 10 min par IP</strong> (anti-force brute), l'admin et le public ont
                   leurs propres quotas. Au-del\xE0, le serveur r\xE9pond <code>429</code>.`},{skillId:"se4.2",html:`Au point ((3)), je [[se4.2|pr\xE9viens les attaques CSRF]] : toute \xE9criture authentifi\xE9e doit
                   pr\xE9senter un <strong>jeton anti-CSRF</strong> valide, sinon <code>403</code>. Un site malveillant
                   ne peut donc pas agir au nom d'un membre connect\xE9.`},{skillId:"se4.3",html:`Au point ((4)), je [[se4.3|durcis les en-t\xEAtes HTTP]] : <code>HSTS</code> (force le HTTPS),
                   <code>nosniff</code> et une <code>CSP</code> limitent les vecteurs d'attaque c\xF4t\xE9 navigateur.`},{skillId:"se4.4",html:`Le tout forme une [[se4.4|cha\xEEne de middlewares]] ordonn\xE9e : chaque requ\xEAte les traverse dans
                   l'ordre, une responsabilit\xE9 par fichier \u2014 simple \xE0 lire, \xE0 tester et \xE0 maintenir.`}]},{id:"trace-5",kind:"trace",number:5,tab:"Front-end \xB7 Routage",title:"Restreindre l'acc\xE8s aux pages d'administration d'une SPA",domain:{label:"Front-end \xB7 Nuxt 3",color:"#8a63e8"},skills:[{id:"se5.1",label:"Structurer une app en pages (Nuxt 3)",color:"#8a63e8"},{id:"se5.2",label:"Router c\xF4t\xE9 client",color:"#2196c9"},{id:"se5.3",label:"Prot\xE9ger les routes (garde de navigation)",color:"#1ea672"}],figure:{type:"code",lang:"js",file:"admin/middleware/auth.global.ts",caption:"Garde de navigation globale : ex\xE9cut\xE9e avant chaque page de l'application d'administration.",legend:[{n:1,cls:"",text:"La page de connexion reste publique"},{n:2,cls:"h2",text:"V\xE9rification de l'identit\xE9 via le cookie (/api/auth/me)"},{n:3,cls:"h3",text:"R\xF4le insuffisant ou erreur \u2192 redirection vers /login"}],lines:[["// auth.global.ts \u2014 garde ex\xE9cut\xE9e AVANT chaque changement de page",0],["export default defineNuxtRouteMiddleware(async (to) => {",0],["  if (to.path === '/login') return                 // page publique",1],["",0],["  const { apiFetch } = useAdminApi()",0],["  try {",0],["    const res = await apiFetch('/api/auth/me')      // qui suis-je ? (cookie)",2],["    const role = res?.data?.role",2],["    if (role !== 'admin') {",3],["      return navigateTo('/login')                   // pas le bon r\xF4le",3],["    }",3],["  } catch {",0],["    return navigateTo('/login')                     // non connect\xE9",3],["  }",0],["})",0]]},general:`<p>La <strong>trace n\xB05</strong> est la <strong>garde de navigation</strong> de l'application
           d'administration. Le site est construit comme une <strong>SPA (application \xE0 page unique)</strong> avec <strong>Nuxt 3</strong> (Vue 3) : les pages sont des
           composants, et la navigation se fait <strong>c\xF4t\xE9 client</strong>, sans rechargement complet.</p>
           <p>Sans elle, n'importe qui pourrait tenter d'ouvrir une page de gestion en tapant son URL : c'est la
           porte d'entr\xE9e de tout l'espace bureau.</p>`,details:[{skillId:"se5.1",html:`L'application est [[se5.1|structur\xE9e en pages]] (routage par fichiers de Nuxt) : une page par
                   \xE9cran de gestion (dossiers, horaires, photos, boutique\u2026), claire et maintenable.`},{skillId:"se5.2",html:`La navigation est [[se5.2|g\xE9r\xE9e c\xF4t\xE9 client]] : changer de page n'entra\xEEne pas un rechargement
                   complet, mais d\xE9clenche d'abord cette garde.`},{skillId:"se5.3",html:`Au point ((2)), la [[se5.3|garde prot\xE8ge les routes]] : elle interroge <code>/api/auth/me</code>
                   (le cookie HttpOnly de la <strong>trace n\xB03</strong>) ; si le r\xF4le n'est pas
                   <code>admin</code> (point ((3))) ou en cas d'erreur, elle <strong>redirige vers la connexion</strong>.
                   La s\xE9curit\xE9 r\xE9elle reste c\xF4t\xE9 serveur \u2014 cette garde am\xE9liore surtout l'exp\xE9rience.`}]},{id:"trace-6",kind:"trace",number:6,tab:"Front-end \xB7 R\xE9activit\xE9",title:"D\xE9velopper un formulaire de pr\xE9-inscription multi-\xE9tapes r\xE9actif",domain:{label:"Front-end \xB7 Vue 3",color:"#8a63e8"},skills:[{id:"se6.1",label:"D\xE9river l'\xE9tat automatiquement (watch)",color:"#8a63e8"},{id:"se6.2",label:"Valider de fa\xE7on r\xE9active (computed + Zod)",color:"#e0871a"},{id:"se6.3",label:"Persister l'\xE9tat (localStorage)",color:"#2196c9"}],figure:{type:"code",lang:"js",file:"composables/usePreInscriptionForm.ts",caption:"Composable Vue 3 pilotant le formulaire de pr\xE9-inscription multi-\xE9tapes (familles).",legend:[{n:1,cls:"",text:"\xC9tat d\xE9riv\xE9 : la liste des judokas suit le nombre saisi"},{n:2,cls:"h2",text:"Validation r\xE9active par \xE9tape (Zod + computed)"},{n:3,cls:"h3",text:"Le brouillon survit \xE0 un rafra\xEEchissement de page"}],lines:[["// usePreInscriptionForm.ts \u2014 formulaire r\xE9actif (Composition API)",0],["const form = ref(defaultForm())",0],["const step = ref(1)",0],["",0],["// La liste des judokas se construit toute seule selon le nombre saisi",0],["watch(() => form.value.nombre_enfants_pratiquants, (n) => {",1],["  const cur = form.value.enfants.length",1],["  if (n > cur) for (let i = cur; i < n; i++) form.value.enfants.push(defaultEnfant())",1],["  else        form.value.enfants = form.value.enfants.slice(0, n)",1],["})",1],["",0],["// Validation d\xE9clarative par \xE9tape (sch\xE9mas Zod)",0],["const representantSchema = z.object({",2],["  email:     z.string().email('Email invalide'),",2],["  telephone: z.string().min(1, 'Le t\xE9l\xE9phone est requis'),",2],["})",2],["const canProceed = computed(() =>                  // recalcul\xE9 automatiquement",2],["  Object.keys(validationErrors.value).length === 0)",2],["",0],["// Le brouillon est sauvegard\xE9 \xE0 chaque frappe \u2192 repris apr\xE8s un refresh",0],["watch(form, (snap) =>",3],["  localStorage.setItem(STORAGE_KEY, JSON.stringify(snap)), { deep: true })",3]]},general:`<p>La <strong>trace n\xB06</strong> est le <strong>composable</strong> qui pilote le formulaire de
           <strong>pr\xE9-inscription</strong> (<code>usePreInscriptionForm.ts</code>) : un parcours en plusieurs
           \xE9tapes, utilisable par des parents press\xE9s, sur mobile.</p>
           <p>C'est le pendant <em>front</em> de la <strong>trace n\xB02</strong> : ici je <strong>recueille et valide</strong>
           les donn\xE9es ; l\xE0-bas, l'API les <strong>enregistre</strong>. Une donn\xE9e propre en amont, c'est moins
           d'erreurs en base.</p>`,details:[{skillId:"se6.1",html:`Au point ((1)), j'[[se6.1|exploite la r\xE9activit\xE9 de Vue]] : un <code>watch</code> ajuste tout
                   seul la liste des judokas quand le parent change leur nombre \u2014 aucun code manuel d'ajout/retrait
                   de champs.`},{skillId:"se6.2",html:`Au point ((2)), la [[se6.2|validation est r\xE9active]] : des sch\xE9mas <strong>Zod</strong> par \xE9tape
                   alimentent un <code>computed</code> <code>canProceed</code> recalcul\xE9 \xE0 chaque frappe, qui active
                   ou bloque le bouton \xAB Suivant \xBB.`},{skillId:"se6.3",html:`Au point ((3)), je [[se6.3|persiste l'\xE9tat]] dans <code>localStorage</code> : si la page est
                   ferm\xE9e ou recharg\xE9e par erreur, le <strong>brouillon est restaur\xE9</strong> \u2014 un vrai confort pour
                   un long formulaire familial.`}]},{id:"bilan",kind:"bilan",tab:"Bilan & analyse",title:"Bilan \u2014 savoir-faire techniques",intro:`J'\xE9value ici mes trois savoir-faire techniques g\xE9n\xE9raux, en variant les domaines
           (<strong>base de donn\xE9es</strong>, <strong>back-end & s\xE9curit\xE9</strong>,
           <strong>front-end</strong>). Chaque savoir-faire est illustr\xE9 par <strong>deux traces</strong> ;
           chaque bloc pr\xE9cise le contexte d'apprentissage et situe mon niveau <em>avant / apr\xE8s</em> le stage.`,scale:["D\xE9butant","Notions","Moyen","Bon","Avanc\xE9"],blocks:[{color:"#2196c9",domain:"Base de donn\xE9es (PostgreSQL)",title:"Concevoir et exploiter une base de donn\xE9es relationnelle",recap:[{k:"Mod\xE9lisation & int\xE9grit\xE9",t:"sch\xE9ma, CASCADE / SET NULL (trace 1) \u2014 R3.07.",tags:["cours","stage"]},{k:"JSONB & index avanc\xE9s",t:"JSONB consentements, 30+ index (trace 1) \u2014 R4.03.",tags:["cours","stage"]},{k:"Transactions & concurrence",t:"withTransaction, ON CONFLICT (trace 2).",tags:["stage","diff"]},{k:"Requ\xEAtes filtr\xE9es & pagin\xE9es",t:"jointures, ILIKE param\xE9tr\xE9, pagination (API dossiers).",tags:["stage"]}],before:2,after:4,justif:`En <strong>R3.07</strong> (SQL en langage de programmation) et <strong>R4.03</strong> (Au-del\xE0 du
               relationnel \u2014 JSONB, full-text search), j'avais acquis les bases de PostgreSQL avec Node.js. Le stage
               m'a fait concevoir un <strong>sch\xE9ma r\xE9el complet</strong> (24 tables) puis \xE9crire des
               <strong>transactions atomiques</strong>, des <strong>requ\xEAtes filtr\xE9es et pagin\xE9es</strong> bien plus
               pouss\xE9es \u2014 progression nette de \xAB Moyen \xBB vers \xAB Avanc\xE9 \xBB.`},{color:"#1ea672",domain:"D\xE9veloppement \xB7 S\xE9curit\xE9",title:"D\xE9velopper un back-end web s\xE9curis\xE9",recap:[{k:"Authentification",t:"bcrypt, JWT + refresh, HttpOnly (trace 3) \u2014 base vue en R3.09.",tags:["cours","stage","diff"]},{k:"API REST & middleware",t:"routes Nitro, handlers (trace 4) \u2014 R3.01 serveur, R4.01.",tags:["cours","stage"]},{k:"D\xE9fense en profondeur",t:"rate-limit, CSRF, en-t\xEAtes (trace 4).",tags:["stage","perso","diff"]},{k:"D\xE9ploiement",t:"VPS, Nginx, PM2, TLS Let's Encrypt.",tags:["perso","diff"]}],before:1,after:3,justif:`En <strong>R3.01 c\xF4t\xE9 serveur</strong> et <strong>R4.01</strong> (Services web Node.js), j'avais
               construit des APIs REST basiques. En <strong>R3.09</strong> (Cryptographie), j'avais vu le hash et
               les bases de JWT. Mais concevoir l'<strong>authentification compl\xE8te</strong> (bcrypt co\xFBt 12, refresh
               hach\xE9 en base, cookie HttpOnly) et la <strong>s\xE9curit\xE9 en profondeur</strong> (rate-limit, CSRF, HSTS)
               sur un projet en production a \xE9t\xE9 apprend en autonomie : ma plus grosse progression, que je situe
               honn\xEAtement \xE0 \xAB Bon \xBB (pas encore \xAB Avanc\xE9 \xBB).`},{color:"#8a63e8",domain:"D\xE9veloppement front-end (Nuxt 3)",title:"D\xE9velopper une interface web dynamique",recap:[{k:"SPA & routage",t:"pages Nuxt, middleware (trace 5) \u2014 R3.01 client, SA\xC9 S3.",tags:["cours","stage"]},{k:"R\xE9activit\xE9 Vue 3",t:"ref / computed / watch (trace 6) \u2014 R3.01 client, R4A.10.",tags:["cours","stage"]},{k:"JWT c\xF4t\xE9 front",t:"intercepteur Axios, refresh automatique (trace 5) \u2014 R4A.10.",tags:["cours","stage"]},{k:"Validation & UX",t:"Zod, formulaire multi-\xE9tapes, localStorage (trace 6).",tags:["stage"]}],before:2,after:4,justif:`En <strong>R3.01 c\xF4t\xE9 client</strong> et la SA\xC9 S3, j'avais d\xE9couvert Vue.js (Pinia, vue-router,
               composants). En <strong>R4A.10</strong> (Compl\xE9ments Web), j'ai approfondi : JWT c\xF4t\xE9 front, Pinia
               avanc\xE9, vue-router pouss\xE9. Passer de ces exercices \xE0 une <strong>SPA Nuxt 3 compl\xE8te</strong> (gardes
               de navigation, composables, formulaires multi-\xE9tapes valid\xE9s par Zod) sur un projet r\xE9el m'a fait
               franchir le cap de \xAB Moyen \xBB \xE0 \xAB Avanc\xE9 \xBB.`}]}]},suivi:{kicker:"Volet 2 \xB7 Suivi de projet",title:"Suivi de projet",summary:`Au-del\xE0 du code, le stage a \xE9t\xE9 un <strong>vrai projet</strong> \xE0 mener dans la dur\xE9e pour un client r\xE9el.
       Trois traces montrent comment j'ai <strong>analys\xE9 les besoins</strong> du club, <strong>tenu un journal de
       bord</strong> et <strong>organis\xE9 et suivi</strong> mon travail, avant le bilan.`,subpages:[{id:"trace-7",kind:"trace",number:7,tab:"Analyse des besoins",title:"Traduire le besoin brut du club en fonctionnalit\xE9s techniques",domain:{label:"Gestion de projet",color:"#e0871a"},skills:[{id:"se7.1",label:"Recueillir et cadrer les besoins (CDC)",color:"#d9576f"},{id:"se7.2",label:"Traduire un besoin en fonctionnalit\xE9s",color:"#8a63e8"},{id:"se7.3",label:"Prioriser et d\xE9couper en sprints",color:"#e0871a"}],figure:{type:"needs",file:"Cahier des charges \u2192 fonctionnalit\xE9s (synth\xE8se)",caption:"Correspondance entre les besoins exprim\xE9s par le club et les fonctionnalit\xE9s livr\xE9es.",legend:[{n:1,cls:"",text:"Un besoin \u2192 plusieurs fonctionnalit\xE9s"},{n:2,cls:"h2",text:"Besoin m\xE9tier traduit en donn\xE9es"},{n:3,cls:"h3",text:"Contrainte l\xE9gale \u2192 solution d\xE9di\xE9e"}],rows:[{need:"\xAB On veut arr\xEAter les inscriptions papier \xBB",feat:"Pr\xE9-inscription en ligne multi-pratiquants + suivi des dossiers",hot:1},{need:"\xAB Le bureau doit g\xE9rer le site sans nous appeler \xBB",feat:"Back-office complet (horaires, \xE9v\xE9nements, photos, boutique, tarifs)",hot:1},{need:"\xAB Suivre la ceinture de chaque judoka \xBB",feat:"Grades par pratiquant (ceinture, date, saison)",hot:2},{need:"\xAB Respecter le RGPD (mineurs, droit \xE0 l'image) \xBB",feat:"Consentements versionn\xE9s & horodat\xE9s (table trace_legale)",hot:3},{need:"\xAB Les parents envoient des photos iPhone illisibles \xBB",feat:"Conversion automatique HEIC \u2192 JPEG \xE0 l'envoi",hot:0},{need:"\xAB Communiquer nos \xE9v\xE9nements et nos tarifs \xBB",feat:"Pages publiques + carrousel d'actualit\xE9s \xE9ditable",hot:0}]},general:`<p>La <strong>trace n\xB07</strong> synth\xE9tise mon travail d'<strong>analyse des besoins</strong> :
           \xE0 gauche, ce que le club exprimait (en langage non technique) ; \xE0 droite, les
           <strong>fonctionnalit\xE9s</strong> que j'en ai d\xE9duites et d\xE9velopp\xE9es.</p>
           <p>Contrairement \xE0 un sujet \xAB cl\xE9 en main \xBB, il a d'abord fallu <strong>comprendre</strong> le
           fonctionnement du club et le formaliser dans un <strong>cahier des charges</strong> avant de coder.</p>`,details:[{skillId:"se7.1",html:`J'ai [[se7.1|recueilli et cadr\xE9 les besoins]] lors de r\xE9unions r\xE9guli\xE8res avec mon tuteur,
                   puis je les ai formalis\xE9s dans un <strong>cahier des charges</strong> et un
                   <strong>dossier d'architecture technique</strong> valid\xE9s en d\xE9but de stage.`},{skillId:"se7.2",html:`J'ai [[se7.2|traduit chaque besoin]] en solution : au point ((1)), \xAB g\xE9rer le site soi-m\xEAme \xBB
                   est devenu <em>plusieurs</em> modules ; au point ((2)), \xAB suivre les ceintures \xBB est devenu une
                   <strong>donn\xE9e</strong> (la table <code>grade</code> de la trace n\xB01).`},{skillId:"se7.3",html:`J'ai [[se7.3|prioris\xE9 et d\xE9coup\xE9 en sprints]] : d'abord les fondations (base, auth, inscription),
                   puis la valeur ajout\xE9e. Le point ((3)) montre une contrainte <strong>l\xE9gale</strong> (RGPD)
                   trait\xE9e par une solution d\xE9di\xE9e (la trace l\xE9gale de la trace n\xB02).`}]},{id:"trace-journal",kind:"trace",number:8,tab:"Journal de bord (Kanban)",title:"Tenir un journal de bord et suivre l'avancement des t\xE2ches",domain:{label:"Gestion de projet",color:"#e0871a"},skills:[{id:"se8j.1",label:"Tenir un journal de bord (tableau Kanban)",color:"#e0871a"},{id:"se8j.2",label:"Suivre et prioriser les t\xE2ches",color:"#2196c9"},{id:"se8j.3",label:"Planifier en sprints et faire des bilans",color:"#1ea672"}],figure:{type:"kanban",file:"Trello \u2014 USPV Judo \xB7 Suivi de projet & gestion de t\xE2ches",caption:"Mon tableau Kanban (Trello) \xE0 mi-projet : les t\xE2ches circulent de colonne en colonne jusqu'\xE0 la \xAB r\xE9colte \xBB.",legend:[{n:1,cls:"",text:"Le flux d'une t\xE2che : du \xAB Bac de d\xE9part \xBB au sprint, puis \xAB En cours \xBB"},{n:2,cls:"h2",text:"Chaque carte porte un co\xFBt en points Fibonacci (2, 3, 5, 7, 11\u2026) estim\xE9 en d\xE9but de sprint"},{n:3,cls:"h3",text:"\xAB R\xE9colte Sprint \xBB : le bilan des t\xE2ches termin\xE9es \u2014 base du BurnUp Chart"}],columns:[{name:"Bac de d\xE9part",hot:1,cards:[{t:"[GESTION] \xC9tude des besoins & cahier des charges",color:"#e0871a"},{t:"[TECH] Audit de l'existant & plan de migration",color:"#2196c9",cost:3},{t:"[DESIGN] Maquettes & charte graphique",color:"#8a63e8",cost:2}]},{name:"Sprint en cours",hot:0,cards:[{t:"[FONCTIONNELLE] Inscription en 4 \xE9tapes",color:"#1ea672",cost:7,hot:2},{t:"[TECH] Admin app (Nuxt) sur le port 3100",color:"#2196c9",cost:5},{t:"[FONCTIONNELLE] Espace Famille (profil, dossiers)",color:"#1ea672",cost:7}]},{name:"En cours",hot:0,cards:[{t:"[FONCTIONNELLE] Admin CMS (horaires, \xE9v\xE9nements)",color:"#1ea672",cost:7},{t:"[DESIGN] Responsive & polish Tailwind",color:"#8a63e8",cost:5}]},{name:"R\xE9colte Sprint 0",hot:3,cards:[{t:"[TECH] Mod\xE9lisation PostgreSQL MCD/MLD",color:"#2196c9",cost:7},{t:"[TECH] Auth JWT + CSRF + rate-limit",color:"#2196c9",cost:11},{t:"[DESIGN] Pages publiques (accueil, contact\u2026)",color:"#8a63e8",cost:5}]}]},general:`<p>La <strong>trace n\xB08</strong> est mon <strong>journal de bord</strong>, tenu sur un
           <strong>tableau Kanban</strong> (outil <strong>Trello</strong>). Un tableau Kanban est une suite de
           <strong>colonnes</strong> repr\xE9sentant les \xE9tapes d'une t\xE2che (\xE0 faire \u2192 en cours \u2192 fait) : on y
           d\xE9place des <strong>cartes</strong> au fil de l'avancement, ce qui donne en un coup d'\u0153il l'\xE9tat du projet.</p>
           <p>J'ai travaill\xE9 en <strong>m\xE9thode agile</strong>, c'est-\xE0-dire par <strong>sprints</strong> \u2014 des cycles
           courts d'environ deux semaines au bout desquels on fait le point. En compl\xE9ment du Kanban, un
           <strong>diagramme de Gantt</strong> (planning des phases) et un
           <strong>BurnUp</strong> (courbe d'avancement)
           m'ont aid\xE9 \xE0 <strong>planifier</strong> et \xE0 mesurer la progression du d\xE9but \xE0 la livraison.</p>`,details:[{skillId:"se8j.1",html:`J'ai [[se8j.1|tenu ce journal de bord]] d\xE8s le premier jour : chaque t\xE2che \u2014 d\xE9veloppement,
                   apprentissage ou organisation \u2014 devient une <strong>carte</strong>. Au point ((1)), les colonnes
                   mat\xE9rialisent le <strong>flux</strong> d'une t\xE2che, du \xAB Bac de d\xE9part \xBB jusqu'\xE0 sa r\xE9alisation.`},{skillId:"se8j.2",html:`Au point ((2)), chaque carte porte un <strong>label de cat\xE9gorie</strong> (<em>[TECH]</em>,
                   <em>[FONCTIONNELLE]</em>, <em>[DESIGN]</em>, <em>[GESTION]</em>), ce qui m'a permis de
                   [[se8j.2|suivre et prioriser]] : voir d'un coup d'\u0153il ce qui restait \xE0 faire et dans quel domaine.`},{skillId:"se8j.3",html:`Au point ((3)), la colonne <strong>\xAB R\xE9colte Sprint \xBB</strong> est le <strong>bilan</strong> de fin de
                   sprint : j'y regroupe les t\xE2ches termin\xE9es pour faire le point avec mon tuteur. C'est ainsi que
                   j'ai [[se8j.3|planifi\xE9 en sprints et fait des bilans]] r\xE9guliers, en lien avec le Gantt et le BurnUp.`}]},{id:"trace-8",kind:"trace",number:9,tab:"Versioning & CI/CD",title:"Versionner le code source et automatiser le d\xE9ploiement (CI/CD)",domain:{label:"Gestion de projet",color:"#e0871a"},skills:[{id:"se8.1",label:"Versionner (Git, commits conventionnels)",color:"#e0871a"},{id:"se8.2",label:"Avancer par it\xE9rations",color:"#2196c9"},{id:"se8.3",label:"Automatiser le d\xE9ploiement (CI/CD)",color:"#1ea672"}],figures:[{type:"gitlog",file:"git log (extrait) \u2014 208 commits",caption:"Extrait de l'historique Git du projet \u2014 208 commits, du d\xE9marrage \xE0 la soutenance.",legend:[{n:1,cls:"",text:"Tout premier commit : d\xE9part du projet"},{n:2,cls:"h2",text:"Livraison d'une fonctionnalit\xE9 (commit \xAB feat \xBB)"}],commits:[{hash:"4373c25",msg:"Doc de base",hot:1},{hash:"73f14db",msg:"feat: Add application source code",hot:2},{hash:"49443bd",msg:"feat: Add project tracking (suivi-de-projet)",hot:0},{hash:"1d2ed17",msg:"feat(seo): sitemap dynamique g\xE9n\xE9r\xE9 depuis la BDD",hot:2},{hash:"bf06a8a",msg:"feat(admin): mode \xE9dition, rappel mot de passe, export VCF",hot:2},{hash:"287bc32",msg:"feat: support photos HEIC (iPhone) avec conversion JPEG",hot:2},{hash:"f1f70ee",msg:"ci(seo): ping IndexNow automatique apr\xE8s d\xE9ploiement r\xE9ussi",hot:0},{hash:"672b629",msg:"fix(security): r\xE9voquer les refresh tokens au changement de mdp",hot:0},{hash:"088c67b",msg:"fix(upload): isoler la conversion HEIC dans un process enfant",hot:0},{hash:"5dd40a0",msg:"fix(seo): corriger l'anti-pattern robots.txt + noindex",hot:0}]},{type:"code",lang:"yaml",file:".github/workflows/deploy.yml (extrait)",caption:"Workflow GitHub Actions du projet : \xE0 chaque push sur main, le site est d\xE9ploy\xE9 en production de bout en bout.",legend:[{n:3,cls:"h3",text:"D\xE9clench\xE9 \xE0 chaque push valid\xE9 sur main : build de l'app et de l'admin, migrations BDD, red\xE9marrage des services."},{n:4,cls:"h4",text:"Fiabilisation : un health-check bloque toute mise en ligne d\xE9faillante ; notification SEO (IndexNow) en fin de d\xE9ploiement."}],lines:[["name: D\xE9ploiement Automatique",0],["on:",3],["  push:",3],["    branches: [main]                  # \xE0 chaque \xE9volution valid\xE9e sur main",3],["jobs:",3],["  deploy:",3],["    runs-on: ubuntu-latest",3],["    steps:",3],["      - uses: actions/checkout@v5",3],["      # Copier le build sur le serveur de prod (SCP, cl\xE9 SSH en secret)",3],["      - uses: appleboy/scp-action@v0.1.7",3],["      # Connexion SSH puis reconstruction et mise en service",3],["      - uses: appleboy/ssh-action@v1.0.3",3],["        with:",3],["          script: |",3],["            npm install && npm run build        # app publique + admin",3],["            npm run migrate:up                  # migrations BDD (node-pg-migrate)",3],["            systemctl restart uspv-public uspv-admin",3],["",0],["            # Health-check : \xE9choue le d\xE9ploiement si l'API ne r\xE9pond pas 200",4],["            curl -fsS http://127.0.0.1:3000/api/health?db=1",4],["      # SEO : notifier IndexNow du sitemap live (\xE9tape non bloquante)",4],["      - name: Notifier IndexNow (recrawl prioritaire)",4],["        if: success()",4]]}],general:`<p>La <strong>trace n\xB09</strong> r\xE9unit deux preuves compl\xE9mentaires : \xE0 gauche l'<strong>historique Git</strong>
           du projet \u2014 <strong>208 commits</strong> qui racontent la progression, du tout premier (point ((1))) jusqu'aux
           derniers correctifs avant la soutenance \u2014 et \xE0 droite le <strong>fichier de configuration</strong> qui
           <strong>automatise la mise en ligne</strong> (int\xE9gration & d\xE9ploiement continus). J'ai adopt\xE9 les
           <strong>commits conventionnels</strong> (<code>feat:</code>, <code>fix:</code>, <code>ci:</code>\u2026).</p>
           <p>Versionner <em>et</em> automatiser le d\xE9ploiement \xE9taient indispensables pour un projet de cette
           ampleur : garder une trace lisible, pouvoir revenir en arri\xE8re, et <strong>fiabiliser</strong> chaque
           mise en production.</p>`,details:[{skillId:"se8.1",html:`J'ai [[se8.1|versionn\xE9 avec Git]] de bout en bout : des commits fr\xE9quents et
                   <strong>typ\xE9s</strong> (point ((2)), les <code>feat:</code>) qui forment un historique
                   imm\xE9diatement lisible.`},{skillId:"se8.2",html:`Le projet a avanc\xE9 par [[se8.2|it\xE9rations]] (sprints) : une fonctionnalit\xE9 \xE0 la fois \u2014 base,
                   authentification, inscription, back-office, boutique, tournoi\u2026 \u2014 chacune test\xE9e puis valid\xE9e
                   avec le tuteur.`},{skillId:"se8.3",html:`J'ai [[se8.3|automatis\xE9 le d\xE9ploiement]] avec <strong>GitHub Actions</strong> (fichier
                   <code>deploy.yml</code>) : au point ((3)), chaque push valid\xE9 sur <code>main</code> d\xE9clenche le
                   <strong>d\xE9ploiement complet</strong> \u2014 build de l'app et de l'admin, <strong>migrations de base de
                   donn\xE9es</strong>, red\xE9marrage des services. Au point ((4)), un <strong>contr\xF4le de sant\xE9</strong>
                   (health-check) bloque toute mise en ligne d\xE9faillante, puis les moteurs de recherche sont notifi\xE9s
                   (IndexNow) \u2014 fini les mises en ligne manuelles risqu\xE9es.`}]},{id:"bilan",kind:"bilan",tab:"Bilan & analyse",title:"Bilan \u2014 suivi de projet",intro:`Mener ce projet sur deux mois pour un client r\xE9el m'a fait progresser sur un savoir-faire de gestion de
           projet que les cours n'abordent que partiellement, faute de projet d'une telle ampleur.`,scale:["D\xE9butant","Notions","Moyen","Bon","Avanc\xE9"],blocks:[{color:"#e0871a",domain:"Gestion de projet",title:"Piloter un projet de d\xE9veloppement, du besoin \xE0 la livraison",recap:[{k:"Recueil & cadrage",t:"r\xE9unions, cahier des charges, DAT (trace 7).",tags:["stage","diff"]},{k:"Traduction & priorisation",t:"du m\xE9tier au technique (trace 7).",tags:["stage"]},{k:"Journal de bord & suivi des t\xE2ches",t:"Kanban Trello, sprints agiles (trace 8).",tags:["stage","diff"]},{k:"Planification",t:"Gantt, BurnUp, bilans de sprint (trace 8).",tags:["cours","stage"]},{k:"Versioning",t:"Git, commits conventionnels (trace 9).",tags:["cours","stage"]},{k:"Int\xE9gration & d\xE9ploiement continus",t:"CI/CD GitHub Actions (trace 9).",tags:["stage","perso","diff"]}],before:1,after:3,justif:`Git et les bases du versioning avaient \xE9t\xE9 vus en <strong>SA\xC9 S3 & S4</strong>. La gestion de projet
               (Kanban, Gantt, sprints) \xE9tait abord\xE9e en cours mais jamais appliqu\xE9e sur <strong>deux mois r\xE9els</strong>,
               du recueil du besoin \xE0 la livraison. Tenir un <strong>journal de bord</strong>, cadrer, m'organiser
               en sprints et <strong>automatiser</strong> le d\xE9ploiement via CI/CD m'a fait passer de \xAB Notions \xBB
               \xE0 \xAB Bon \xBB.`}]}]},integration:{kicker:"Volet 3 \xB7 Int\xE9gration & travail en entreprise",title:"Int\xE9gration en entreprise",summary:`Un stage, c'est aussi s'int\xE9grer dans une structure et travailler avec ses membres. Deux traces
       montrent comment j'ai <strong>accompagn\xE9 les utilisateurs</strong> (la documentation du bureau) et comment
       j'ai \xE9t\xE9 <strong>force de proposition</strong> en agissant en <strong>autonomie</strong>.`,subpages:[{id:"trace-9",kind:"trace",number:10,tab:"Documentation",title:"R\xE9diger un guide d'utilisation pour autonomiser le bureau",domain:{label:"Communication",color:"#d9576f"},skills:[{id:"se9.1",label:"R\xE9diger une documentation claire",color:"#d9576f"},{id:"se9.2",label:"Vulgariser pour l'utilisateur",color:"#e0871a"},{id:"se9.3",label:"Accompagner par l'interface (UX)",color:"#2196c9"}],figure:{type:"doc",file:"GUIDE_BUREAU.md",caption:"Extrait du guide remis au bureau pour qu'il g\xE8re le site en toute autonomie.",legend:[{n:1,cls:"",text:"Sommaire structur\xE9 par t\xE2che concr\xE8te"},{n:2,cls:"h2",text:"Vulgarisation (explication des statuts de dossier)"},{n:3,cls:"h3",text:"FAQ : anticiper les questions des b\xE9n\xE9voles"}],doc:{title:"Guide du bureau \u2014 g\xE9rer le site USPV Judo",sommaire:["1. Se connecter \xE0 l'espace de gestion","2. Valider une pr\xE9-inscription (les dossiers)","3. Mettre \xE0 jour les horaires et les tarifs","4. Publier un \xE9v\xE9nement et des photos","5. G\xE9rer la boutique et les ceintures"],sommaireHot:1,extract:{heading:"2. Comprendre les statuts d'un dossier",text:"\xAB En attente : la famille vient de s'inscrire. Incomplet : il manque un justificatif (certificat m\xE9dical\u2026). Valid\xE9 : le dossier est complet, l'adh\xE9sion est enregistr\xE9e. Vous n'avez qu'\xE0 cliquer pour faire passer un dossier d'un statut \xE0 l'autre. \xBB",hot:2},faq:{q:"\xAB Le bouton Enregistrer reste gris\xE9 : pensez \xE0 activer le mode \xE9dition en haut de page. \xBB",hot:3}}},general:`<p>La <strong>trace n\xB010</strong> est le <strong><a href="GUIDE-UTILISATION.pdf" target="_blank" class="rlink">guide d'utilisation</a></strong> que j'ai r\xE9dig\xE9 pour le
           bureau. Construire l'outil ne suffit pas : pour rendre des <strong>b\xE9n\xE9voles non informaticiens</strong>
           r\xE9ellement autonomes, il fallait un <a href="GUIDE-UTILISATION.pdf" target="_blank" class="rlink">guide</a> qu'ils suivent seuls.</p>
           <p>C'est un livrable de <strong>communication</strong> qui assure la <strong>p\xE9rennit\xE9</strong> du projet
           apr\xE8s mon d\xE9part.</p>`,details:[{skillId:"se9.1",html:`J'ai [[se9.1|r\xE9dig\xE9 une documentation claire]], orient\xE9e <strong>t\xE2ches concr\xE8tes</strong>
                   (point ((1))) plut\xF4t que fonctions techniques, avec une FAQ (point ((3))) r\xE9pondant par avance
                   aux blocages courants.`},{skillId:"se9.2",html:`J'ai [[se9.2|vulgaris\xE9]] en me mettant \xE0 la place d'un b\xE9n\xE9vole : au point ((2)), j'explique les
                   <strong>statuts d'un dossier</strong> avec des mots simples, sans jargon.`},{skillId:"se9.3",html:`J'ai aussi [[se9.3|accompagn\xE9 par l'interface]] elle-m\xEAme : un <strong>\xAB mode \xE9dition \xBB</strong>
                   explicite et des <strong>rappels de sauvegarde</strong> guident l'utilisateur et \xE9vitent les
                   fausses man\u0153uvres \u2014 la doc et l'UX se compl\xE8tent.`}]},{id:"trace-10",kind:"trace",number:11,tab:"Autonomie & proposition",title:"Proposer et concevoir un module additionnel hors cahier des charges",domain:{label:"Travail en entreprise",color:"#d9576f"},skills:[{id:"se10.1",label:"Comprendre l'organisation du club",color:"#d9576f"},{id:"se10.2",label:"\xCAtre force de proposition",color:"#e0871a"},{id:"se10.3",label:"Agir en autonomie mesur\xE9e",color:"#1ea672"}],figure:{type:"chat",file:"Module Tournoi (proposition valid\xE9e en r\xE9union)",caption:"Le module d'inscription au tournoi : une fonctionnalit\xE9 que j'ai propos\xE9e hors cahier des charges.",legend:[{n:1,cls:"",text:"Besoin r\xE9el observ\xE9 : gestion du tournoi annuel"},{n:2,cls:"h2",text:"Proposition spontan\xE9e : inscription en ligne des clubs"},{n:3,cls:"h3",text:"Solution livr\xE9e en autonomie"}],thread:[{who:"animateur",name:"Le bureau",text:"Chaque ann\xE9e on organise le tournoi du club. Aujourd'hui les autres clubs nous envoient leurs judokas par e-mail : c'est long et source d'erreurs.",hot:1},{who:"me",name:"Moi (stagiaire)",text:"Et si chaque club s'inscrivait en ligne avec un code, et saisissait lui-m\xEAme ses participants (poids, grade, cat\xE9gorie) ?",hot:2},{who:"animateur",name:"Le bureau",text:"Ce serait parfait \u2014 on n'avait pas os\xE9 le demander.",hot:0},{who:"me",name:"Moi (stagiaire)",text:"Je le d\xE9veloppe : module Tournoi avec acc\xE8s par club, valid\xE9 puis test\xE9 avant la mise en ligne.",hot:3}]},general:`<p>La <strong>trace n\xB011</strong> est le <strong>module Tournoi</strong> que j'ai con\xE7u. Il n'\xE9tait
           <em>pas</em> dans le cahier des charges : en discutant avec le bureau, j'ai compris que le club
           <strong>organise un tournoi annuel</strong> et g\xE8re p\xE9niblement les inscriptions des clubs invit\xE9s par
           e-mail. J'ai donc <strong>propos\xE9</strong> un module d\xE9di\xE9.</p>
           <p>Il illustre mon <strong>int\xE9gration</strong> : comprendre l'organisation pour proposer un outil utile,
           et le r\xE9aliser en autonomie.</p>`,details:[{skillId:"se10.1",html:`Pour ce module, j'ai d\xFB [[se10.1|comprendre l'organisation du club]] : comment se d\xE9roule le
                   tournoi, qui inscrit qui (point ((1))), et quelles informations sont n\xE9cessaires (poids, grade,
                   cat\xE9gorie d'\xE2ge FFJDA).`},{skillId:"se10.2",html:`J'ai \xE9t\xE9 [[se10.2|force de proposition]] : l'inscription en ligne par club (point ((2))) est une
                   id\xE9e que j'ai apport\xE9e spontan\xE9ment, valid\xE9e en r\xE9union \u2014 pas une simple commande \xE0 ex\xE9cuter.`},{skillId:"se10.3",html:`J'ai [[se10.3|agi en autonomie mesur\xE9e]] : proposer, faire valider, puis livrer (point ((3))) un
                   module complet (acc\xE8s par code, saisie des participants, finalisation) \u2014 sans partir dans des
                   d\xE9veloppements non prioritaires.`}]},{id:"bilan",kind:"bilan",tab:"Bilan & analyse",title:"Bilan \u2014 int\xE9gration en entreprise",intro:`Ces savoir-faire \xAB humains \xBB se travaillent difficilement en cours : c'est l'immersion qui les d\xE9veloppe.
           Le stage a \xE9t\xE9 ma premi\xE8re exp\xE9rience de ce type dans une structure r\xE9elle.`,scale:["D\xE9butant","Notions","Moyen","Bon","Avanc\xE9"],blocks:[{color:"#d9576f",domain:"Travail en entreprise",title:"S'int\xE9grer et accompagner les utilisateurs en entreprise",recap:[{k:"Comprendre l'organisation",t:"saisir le fonctionnement du club (trace 11).",tags:["stage"]},{k:"Force de proposition",t:"proposer le module Tournoi (trace 11).",tags:["stage","diff"]},{k:"Autonomie mesur\xE9e",t:"proposer \u2192 valider \u2192 livrer (trace 11).",tags:["stage","perso"]},{k:"Documentation & vulgarisation",t:'le <a href="GUIDE-UTILISATION.pdf" target="_blank" class="rlink">guide du bureau</a> (trace 10).',tags:["cours","stage"]}],before:1,after:3,justif:`Premi\xE8re vraie immersion associative : j'ai appris \xE0 <strong>m'int\xE9grer</strong>, \xE0 oser
               <strong>proposer</strong>, \xE0 travailler en autonomie et \xE0 <strong>accompagner</strong> des utilisateurs
               r\xE9els non techniques par une documentation claire. Progression de \xAB Notions \xBB \xE0 \xAB Bon \xBB.`}]}]}};
